static void bbr_on_init(quicly_bbr_cc_bbr *bbr, quicly_bbr_conn_stat *cstat,
                        quicly_bbr_tstamp initial_ts) {
  quicly_bbr_wf_init(&bbr->max_bw_filter, QUICLY_BBR_BBR_MAX_BW_FILTERLEN);
  quicly_bbr_wf_init(&bbr->extra_acked_filter, QUICLY_BBR_BBR_EXTRA_ACKED_FILTERLEN);

  bbr->min_rtt =
    cstat->first_rtt_sample_ts == UINT64_MAX ? UINT64_MAX : cstat->smoothed_rtt;
  bbr->min_rtt_stamp = initial_ts;
  /* remark: Use UINT64_MAX instead of 0 for consistency. */
  bbr->probe_rtt_done_stamp = UINT64_MAX;
  bbr->probe_rtt_round_done = 0;
  bbr->prior_cwnd = 0;
  bbr->idle_restart = 0;
  bbr->extra_acked_interval_start = initial_ts;
  bbr->extra_acked_delivered = 0;
  bbr->full_bw_reached = 0;

  bbr_reset_congestion_signals(bbr);
  bbr_reset_shortterm_model(bbr);
  bbr_init_round_counting(bbr);
  bbr_reset_full_bw(bbr);
  bbr_init_pacing_rate(bbr, cstat);
  bbr_enter_startup(bbr);

  cstat->send_quantum = cstat->max_tx_udp_payload_size * 10;

  /* Missing in documentation */
  bbr->loss_round_start = 0;
  bbr->loss_round_delivered = UINT64_MAX;

  bbr->rounds_since_probe_up = 0;

  bbr->max_bw = 0;
  bbr->bw = 0;

  bbr->cycle_count = 0;

  bbr->extra_acked = 0;

  bbr->bytes_lost_in_round = 0;
  bbr->loss_events_in_round = 0;

  bbr->offload_budget = 0;

  bbr->probe_up_acked_per_inc = UINT64_MAX;
  bbr->cycle_stamp = UINT64_MAX;
  bbr->ack_phase = QUICLY_BBR_BBR_ACK_PHASE_ACKS_INIT;
  bbr->bw_probe_wait = 0;
  bbr->is_bw_probe_sample = 0;
  bbr->bw_probe_up_rounds = 0;
  bbr->bw_probe_up_acked = 0;
  bbr->prev_probe_too_high = 0;
  bbr->prev_probe_precautionary = 0;

  bbr->inflight_longterm = UINT64_MAX;

  bbr->probe_rtt_expired = 0;
  bbr->probe_rtt_min_delay = UINT64_MAX;
  bbr->probe_rtt_min_stamp = initial_ts;

  bbr->in_loss_recovery = 0;
  bbr->round_count_at_recovery = UINT64_MAX;

  bbr->max_inflight = 0;

  bbr->bdp = 0;
  bbr->drain_start_round = 0;

  bbr->undo_loss_in_round = 0;
  bbr->undo_state = QUICLY_BBR_BBR_STATE_NONE;
  bbr->undo_bw_shortterm = 0;
  bbr->undo_inflight_shortterm = 0;
  bbr->undo_inflight_longterm = 0;
}

static void bbr_reset_congestion_signals(quicly_bbr_cc_bbr *bbr) {
  bbr->is_loss_in_round = 0;
  bbr->bw_latest = 0;
  bbr->inflight_latest = 0;
}

static void bbr_reset_shortterm_model(quicly_bbr_cc_bbr *bbr) {
  bbr->bw_shortterm = UINT64_MAX;
  bbr->inflight_shortterm = UINT64_MAX;
}

static void bbr_init_round_counting(quicly_bbr_cc_bbr *bbr) {
  bbr->next_round_delivered = 0;
  bbr->round_start = 0;
  bbr->round_count = 0;
}

static void bbr_reset_full_bw(quicly_bbr_cc_bbr *bbr) {
  bbr->full_bw = 0;
  bbr->full_bw_count = 0;
  bbr->full_bw_now = 0;
}

static void bbr_check_full_bw_reached(quicly_bbr_cc_bbr *bbr,
                                      const quicly_bbr_conn_stat *cstat) {
  if (bbr->full_bw_now || !bbr->round_start || bbr->rst->rs.is_app_limited) {
    return;
  }

  if (cstat->delivery_rate_sec * 100 >= bbr->full_bw * 125) {
    bbr_reset_full_bw(bbr);
    bbr->full_bw = cstat->delivery_rate_sec;

    return;
  }

  ++bbr->full_bw_count;

  bbr->full_bw_now = bbr->full_bw_count >= 3;
  if (!bbr->full_bw_now) {
    return;
  }

  bbr->full_bw_reached = 1;

  quicly_bbr_log_infof(bbr->cc.log, QUICLY_BBR_LOG_EVENT_CCA,
                   "bbr reached full bandwidth, full_bw=", bbr->full_bw);
}

static void bbr_check_startup_high_loss(quicly_bbr_cc_bbr *bbr) {
  if (bbr->full_bw_reached || bbr->loss_events_in_round <= 6 ||
      (bbr->in_loss_recovery &&
       bbr->round_count <= bbr->round_count_at_recovery) ||
      !bbr_is_inflight_too_high(bbr, &bbr->rst->rs)) {
    return;
  }

  bbr->full_bw_reached = 1;
  bbr->inflight_longterm =
    quicly_bbr_max(bbr_bdp_multiple(bbr, bbr->cwnd_gain_h), bbr->inflight_latest);
}

static void bbr_init_pacing_rate(const quicly_bbr_cc_bbr *bbr,
                                 quicly_bbr_conn_stat *cstat) {
  cstat->pacing_interval_m =
    quicly_bbr_max(((cstat->first_rtt_sample_ts == UINT64_MAX ? QUICLY_BBR_MILLISECONDS
                                                          : cstat->smoothed_rtt)
                << 10) *
                 100 / QUICLY_BBR_BBR_STARTUP_PACING_GAIN_H / bbr->initial_cwnd,
               1);
}

static void bbr_set_pacing_rate_with_gain(const quicly_bbr_cc_bbr *bbr,
                                          quicly_bbr_conn_stat *cstat,
                                          uint64_t pacing_gain_h) {
  uint64_t interval_m;

  if (bbr->bw == 0) {
    return;
  }

  interval_m = (QUICLY_BBR_SECONDS << 10) * 100 * 100 / pacing_gain_h / bbr->bw /
               (100 - QUICLY_BBR_BBR_PACING_MARGIN_PERCENT);
  interval_m = quicly_bbr_max(interval_m, 1);

  if (bbr->full_bw_reached || interval_m < cstat->pacing_interval_m) {
    cstat->pacing_interval_m = interval_m;
  }
}

static void bbr_set_pacing_rate(const quicly_bbr_cc_bbr *bbr,
                                quicly_bbr_conn_stat *cstat) {
  bbr_set_pacing_rate_with_gain(bbr, cstat, bbr->pacing_gain_h);
}

static void bbr_enter_startup(quicly_bbr_cc_bbr *bbr) {
  quicly_bbr_log_info(bbr->cc.log, QUICLY_BBR_LOG_EVENT_CCA, "bbr enter Startup");

  bbr->state = QUICLY_BBR_BBR_STATE_STARTUP;
  bbr->pacing_gain_h = QUICLY_BBR_BBR_STARTUP_PACING_GAIN_H;
  bbr->cwnd_gain_h = QUICLY_BBR_BBR_DEFAULT_CWND_GAIN_H;
}

static void bbr_check_startup_done(quicly_bbr_cc_bbr *bbr) {
  bbr_check_startup_high_loss(bbr);

  if (bbr->state == QUICLY_BBR_BBR_STATE_STARTUP && bbr->full_bw_reached) {
    bbr_enter_drain(bbr);
  }
}

static void bbr_on_transmit(quicly_bbr_cc_bbr *bbr, quicly_bbr_conn_stat *cstat,
                            quicly_bbr_tstamp ts) {
  bbr_handle_restart_from_idle(bbr, cstat, ts);
}

static void bbr_update_on_ack(quicly_bbr_cc_bbr *bbr, quicly_bbr_conn_stat *cstat,
                              const quicly_bbr_cc_ack *ack, quicly_bbr_tstamp ts) {
  bbr_update_model_and_state(bbr, cstat, ack, ts);
  bbr_update_control_parameters(bbr, cstat, ack);

  /* Keep the completed round's evidence through ProbeBW model updates. */
  if (bbr->round_start) {
    bbr->rst->is_cwnd_limited = 0;
  }
}

static void bbr_update_model_and_state(quicly_bbr_cc_bbr *bbr,
                                       quicly_bbr_conn_stat *cstat,
                                       const quicly_bbr_cc_ack *ack,
                                       quicly_bbr_tstamp ts) {
  bbr_update_latest_delivery_signals(bbr, cstat);
  bbr_update_congestion_signals(bbr, cstat, ack);
  bbr_update_ack_aggregation(bbr, cstat, ack, ts);
  bbr_check_full_bw_reached(bbr, cstat);
  bbr_check_startup_done(bbr);
  bbr_check_drain_done(bbr, cstat, ts);
  bbr_update_probe_bw_cycle_phase(bbr, cstat, ack, ts);
  bbr_update_min_rtt(bbr, ack, ts);
  bbr_check_probe_rtt(bbr, cstat, ts);
  bbr_advance_latest_delivery_signals(bbr, cstat);
  bbr_bound_bw_for_model(bbr);
}

static void bbr_update_control_parameters(quicly_bbr_cc_bbr *bbr,
                                          quicly_bbr_conn_stat *cstat,
                                          const quicly_bbr_cc_ack *ack) {
  bbr_set_pacing_rate(bbr, cstat);
  bbr_set_send_quantum(bbr, cstat);
  bbr_set_cwnd(bbr, cstat, ack);
}

static void bbr_update_latest_delivery_signals(quicly_bbr_cc_bbr *bbr,
                                               const quicly_bbr_conn_stat *cstat) {
  bbr->loss_round_start = 0;
  bbr->bw_latest = quicly_bbr_max(bbr->bw_latest, cstat->delivery_rate_sec);
  bbr->inflight_latest =
    quicly_bbr_max(bbr->inflight_latest, bbr->rst->rs.delivered);

  if (bbr->rst->rs.prior_delivered >= bbr->loss_round_delivered) {
    bbr->loss_round_delivered = bbr->rst->delivered;
    bbr->loss_round_start = 1;
  }
}

static void bbr_advance_latest_delivery_signals(quicly_bbr_cc_bbr *bbr,
                                                const quicly_bbr_conn_stat *cstat) {
  if (bbr->loss_round_start) {
    bbr->bw_latest = cstat->delivery_rate_sec;
    bbr->inflight_latest = bbr->rst->rs.delivered;
  }
}

static void bbr_update_congestion_signals(quicly_bbr_cc_bbr *bbr,
                                          const quicly_bbr_conn_stat *cstat,
                                          const quicly_bbr_cc_ack *ack) {
  bbr_update_max_bw(bbr, cstat, ack);

  if (ack->bytes_lost) {
    bbr->bytes_lost_in_round += ack->bytes_lost;
    ++bbr->loss_events_in_round;
  }

  if (!bbr->loss_round_start) {
    return;
  }

  bbr_adapt_lower_bounds_from_congestion(bbr, cstat);

  bbr->is_loss_in_round = 0;
  bbr->undo_loss_in_round = 0;
}

static void
bbr_adapt_lower_bounds_from_congestion(quicly_bbr_cc_bbr *bbr,
                                       const quicly_bbr_conn_stat *cstat) {
  if (bbr_is_probing_bw(bbr)) {
    return;
  }

  if (bbr->is_loss_in_round) {
    bbr_init_lower_bounds(bbr, cstat);
    bbr_loss_lower_bounds(bbr);
  }
}

static void bbr_init_lower_bounds(quicly_bbr_cc_bbr *bbr,
                                  const quicly_bbr_conn_stat *cstat) {
  if (bbr->bw_shortterm == UINT64_MAX) {
    bbr->bw_shortterm = bbr->max_bw;
  }

  if (bbr->inflight_shortterm == UINT64_MAX) {
    bbr->inflight_shortterm = cstat->cwnd;
  }
}

static void bbr_loss_lower_bounds(quicly_bbr_cc_bbr *bbr) {
  bbr->bw_shortterm =
    quicly_bbr_max(bbr->bw_latest, bbr->bw_shortterm * QUICLY_BBR_BBR_BETA_NUMER /
                                 QUICLY_BBR_BBR_BETA_DENOM);
  bbr->inflight_shortterm = quicly_bbr_max(
    bbr->inflight_latest,
    bbr->inflight_shortterm * QUICLY_BBR_BBR_BETA_NUMER / QUICLY_BBR_BBR_BETA_DENOM);
}

static void bbr_bound_bw_for_model(quicly_bbr_cc_bbr *bbr) {
  bbr->bw = quicly_bbr_min(bbr->max_bw, bbr->bw_shortterm);
}

static void bbr_update_max_bw(quicly_bbr_cc_bbr *bbr, const quicly_bbr_conn_stat *cstat,
                              const quicly_bbr_cc_ack *ack) {
  bbr_update_round(bbr, ack);

  if (cstat->delivery_rate_sec && (cstat->delivery_rate_sec >= bbr->max_bw ||
                                   !bbr->rst->rs.is_app_limited)) {
    quicly_bbr_wf_update(&bbr->max_bw_filter, cstat->delivery_rate_sec,
                     bbr->cycle_count);

    bbr->max_bw = quicly_bbr_wf_get_best(&bbr->max_bw_filter);
  }
}

static void bbr_update_round(quicly_bbr_cc_bbr *bbr, const quicly_bbr_cc_ack *ack) {
  if (ack->pkt_delivered >= bbr->next_round_delivered) {
    bbr_start_round(bbr);

    ++bbr->round_count;
    ++bbr->rounds_since_probe_up;
    bbr->round_start = 1;

    bbr->bytes_lost_in_round = 0;
    bbr->loss_events_in_round = 0;

    return;
  }

  bbr->round_start = 0;
}

static void bbr_start_round(quicly_bbr_cc_bbr *bbr) {
  bbr->next_round_delivered = bbr->rst->delivered;
}

static int bbr_is_in_probe_bw_state(const quicly_bbr_cc_bbr *bbr) {
  switch (bbr->state) {
  case QUICLY_BBR_BBR_STATE_PROBE_BW_DOWN:
  case QUICLY_BBR_BBR_STATE_PROBE_BW_CRUISE:
  case QUICLY_BBR_BBR_STATE_PROBE_BW_REFILL:
  case QUICLY_BBR_BBR_STATE_PROBE_BW_UP:
    return 1;
  default:
    return 0;
  }
}

static int bbr_is_probing_bw(const quicly_bbr_cc_bbr *bbr) {
  switch (bbr->state) {
  case QUICLY_BBR_BBR_STATE_STARTUP:
  case QUICLY_BBR_BBR_STATE_PROBE_BW_REFILL:
  case QUICLY_BBR_BBR_STATE_PROBE_BW_UP:
    return 1;
  default:
    return 0;
  }
}

static void bbr_update_ack_aggregation(quicly_bbr_cc_bbr *bbr,
                                       const quicly_bbr_conn_stat *cstat,
                                       const quicly_bbr_cc_ack *ack,
                                       quicly_bbr_tstamp ts) {
  quicly_bbr_duration interval = ts - bbr->extra_acked_interval_start;
  uint64_t expected_delivered = bbr->bw * interval / QUICLY_BBR_SECONDS;
  uint64_t extra;

  if (bbr->extra_acked_delivered <= expected_delivered) {
    bbr->extra_acked_delivered = 0;
    bbr->extra_acked_interval_start = ts;
    expected_delivered = 0;
  }

  bbr->extra_acked_delivered += ack->bytes_delivered;

  if (bbr->extra_acked_delivered <= expected_delivered) {
    extra = 0;
  } else {
    extra = bbr->extra_acked_delivered - expected_delivered;
    extra = quicly_bbr_min(extra, cstat->cwnd);
  }

  if (bbr->full_bw_reached) {
    bbr->extra_acked_filter.win = QUICLY_BBR_BBR_EXTRA_ACKED_FILTERLEN;
  } else {
    bbr->extra_acked_filter.win = 1;
  }

  quicly_bbr_wf_update(&bbr->extra_acked_filter, extra, bbr->round_count);

  bbr->extra_acked = quicly_bbr_wf_get_best(&bbr->extra_acked_filter);
}

static void bbr_enter_drain(quicly_bbr_cc_bbr *bbr) {
  quicly_bbr_log_info(bbr->cc.log, QUICLY_BBR_LOG_EVENT_CCA, "bbr enter Drain");

  bbr->state = QUICLY_BBR_BBR_STATE_DRAIN;
  bbr->pacing_gain_h = QUICLY_BBR_BBR_DRAIN_PACING_GAIN_H;
  bbr->cwnd_gain_h = QUICLY_BBR_BBR_DEFAULT_CWND_GAIN_H;
  bbr->drain_start_round = bbr->round_count;
}

static void bbr_check_drain_done(quicly_bbr_cc_bbr *bbr,
                                 const quicly_bbr_conn_stat *cstat,
                                 quicly_bbr_tstamp ts) {
  if (bbr->state == QUICLY_BBR_BBR_STATE_DRAIN &&
      (cstat->bytes_in_flight <= bbr_inflight(bbr, cstat, 100) ||
       bbr->round_count >
         bbr->drain_start_round + QUICLY_BBR_BBR_MAX_DRAIN_ROUNDS)) {
    bbr_enter_probe_bw(bbr, ts);
  }
}

static void bbr_enter_probe_bw(quicly_bbr_cc_bbr *bbr, quicly_bbr_tstamp ts) {
  bbr_start_probe_bw_down(bbr, ts);
}

static void bbr_start_probe_bw_down(quicly_bbr_cc_bbr *bbr, quicly_bbr_tstamp ts) {
  quicly_bbr_log_info(bbr->cc.log, QUICLY_BBR_LOG_EVENT_CCA, "bbr start ProbeBW_DOWN");

  bbr_reset_congestion_signals(bbr);

  bbr->probe_up_acked_per_inc = UINT64_MAX;

  bbr_pick_probe_wait(bbr);

  bbr->cycle_stamp = ts;
  bbr->ack_phase = QUICLY_BBR_BBR_ACK_PHASE_ACKS_PROBE_STOPPING;

  bbr_start_round(bbr);

  bbr->state = QUICLY_BBR_BBR_STATE_PROBE_BW_DOWN;
  bbr->pacing_gain_h = 90;
  bbr->cwnd_gain_h = QUICLY_BBR_BBR_DEFAULT_CWND_GAIN_H;
}

static void bbr_start_probe_bw_cruise(quicly_bbr_cc_bbr *bbr) {
  quicly_bbr_log_info(bbr->cc.log, QUICLY_BBR_LOG_EVENT_CCA,
                  "bbr start ProbeBW_CRUISE");

  bbr->state = QUICLY_BBR_BBR_STATE_PROBE_BW_CRUISE;
  bbr->pacing_gain_h = 100;
  bbr->cwnd_gain_h = QUICLY_BBR_BBR_DEFAULT_CWND_GAIN_H;
}

static void bbr_start_probe_bw_refill(quicly_bbr_cc_bbr *bbr) {
  quicly_bbr_log_info(bbr->cc.log, QUICLY_BBR_LOG_EVENT_CCA,
                  "bbr start ProbeBW_REFILL");

  bbr_reset_shortterm_model(bbr);

  bbr->bw_probe_up_rounds = 0;
  bbr->bw_probe_up_acked = 0;
  bbr->prev_probe_precautionary = 0;
  bbr->ack_phase = QUICLY_BBR_BBR_ACK_PHASE_ACKS_REFILLING;

  bbr_start_round(bbr);

  bbr->state = QUICLY_BBR_BBR_STATE_PROBE_BW_REFILL;
  bbr->pacing_gain_h = 100;
  bbr->cwnd_gain_h = QUICLY_BBR_BBR_DEFAULT_CWND_GAIN_H;
}

static void bbr_start_probe_bw_up(quicly_bbr_cc_bbr *bbr,
                                  const quicly_bbr_conn_stat *cstat) {
  quicly_bbr_log_info(bbr->cc.log, QUICLY_BBR_LOG_EVENT_CCA, "bbr start ProbeBW_UP");

  bbr->ack_phase = QUICLY_BBR_BBR_ACK_PHASE_ACKS_PROBE_STARTING;

  bbr_start_round(bbr);
  bbr_reset_full_bw(bbr);

  bbr->full_bw = cstat->delivery_rate_sec;
  bbr->state = QUICLY_BBR_BBR_STATE_PROBE_BW_UP;
  bbr->pacing_gain_h = 125;
  bbr->cwnd_gain_h = 225;

  bbr_raise_inflight_longterm_slope(bbr, cstat);
}

static void bbr_update_probe_bw_cycle_phase(quicly_bbr_cc_bbr *bbr,
                                            const quicly_bbr_conn_stat *cstat,
                                            const quicly_bbr_cc_ack *ack,
                                            quicly_bbr_tstamp ts) {
  if (!bbr->full_bw_reached) {
    return;
  }

  if (bbr_adapt_longterm_model(bbr, cstat, ack)) {
    return;
  }

  if (!bbr_is_in_probe_bw_state(bbr)) {
    return;
  }

  switch (bbr->state) {
  case QUICLY_BBR_BBR_STATE_PROBE_BW_DOWN:
    if (bbr_is_time_to_probe_bw(bbr, cstat, ts)) {
      return;
    }

    if (bbr_is_time_to_cruise(bbr, cstat)) {
      bbr_start_probe_bw_cruise(bbr);
    }

    break;
  case QUICLY_BBR_BBR_STATE_PROBE_BW_CRUISE:
    if (bbr_is_time_to_probe_bw(bbr, cstat, ts)) {
      return;
    }

    break;
  case QUICLY_BBR_BBR_STATE_PROBE_BW_REFILL:
    if (bbr->round_start) {
      bbr->is_bw_probe_sample = 1;
      bbr_start_probe_bw_up(bbr, cstat);
    }

    break;
  case QUICLY_BBR_BBR_STATE_PROBE_BW_UP:
    if (bbr_is_time_to_go_down(bbr, cstat)) {
      bbr->prev_probe_too_high = 0;
      bbr_start_probe_bw_down(bbr, ts);
    }

    break;
  default:
    break;
  }
}

static int bbr_is_time_to_cruise(quicly_bbr_cc_bbr *bbr,
                                 const quicly_bbr_conn_stat *cstat) {
  uint64_t inflight = quicly_bbr_min(bbr_inflight_with_headroom(bbr, cstat),
                                 bbr_inflight(bbr, cstat, 100));

  return cstat->bytes_in_flight <= inflight;
}

static int bbr_is_time_to_go_down(quicly_bbr_cc_bbr *bbr,
                                  const quicly_bbr_conn_stat *cstat) {
  if (bbr->prev_probe_too_high &&
      cstat->bytes_in_flight >= bbr->inflight_longterm) {
    bbr->prev_probe_precautionary = 1;

    return 1;
  }

  if (bbr->rst->is_cwnd_limited && cstat->cwnd >= bbr->inflight_longterm) {
    bbr_reset_full_bw(bbr);
    bbr->full_bw = cstat->delivery_rate_sec;

    return 0;
  }

  return bbr->full_bw_now;
}

static int bbr_has_elapsed_in_phase(const quicly_bbr_cc_bbr *bbr,
                                    quicly_bbr_duration interval,
                                    quicly_bbr_tstamp ts) {
  return ts > bbr->cycle_stamp + interval;
}

static uint64_t bbr_inflight_with_headroom(const quicly_bbr_cc_bbr *bbr,
                                           const quicly_bbr_conn_stat *cstat) {
  uint64_t headroom;
  uint64_t mpcwnd;
  if (bbr->inflight_longterm == UINT64_MAX) {
    return UINT64_MAX;
  }

  headroom = quicly_bbr_max((uint64_t)cstat->max_tx_udp_payload_size,
                        bbr->inflight_longterm * QUICLY_BBR_BBR_HEADROOM_NUMER /
                          QUICLY_BBR_BBR_HEADROOM_DENOM);
  mpcwnd = min_pipe_cwnd(cstat->max_tx_udp_payload_size);

  if (bbr->inflight_longterm > headroom) {
    return quicly_bbr_max(bbr->inflight_longterm - headroom, mpcwnd);
  }

  return mpcwnd;
}

static void bbr_raise_inflight_longterm_slope(quicly_bbr_cc_bbr *bbr,
                                              const quicly_bbr_conn_stat *cstat) {
  uint64_t growth_this_round = 1ULL << bbr->bw_probe_up_rounds;

  bbr->bw_probe_up_rounds = quicly_bbr_min(bbr->bw_probe_up_rounds + 1, 30);
  bbr->probe_up_acked_per_inc =
    quicly_bbr_max(cstat->cwnd / growth_this_round, cstat->max_tx_udp_payload_size);
}

static void bbr_probe_inflight_longterm_upward(quicly_bbr_cc_bbr *bbr,
                                               const quicly_bbr_conn_stat *cstat,
                                               const quicly_bbr_cc_ack *ack) {
  uint64_t delta;

  if (!bbr->rst->is_cwnd_limited || cstat->cwnd < bbr->inflight_longterm) {
    return;
  }

  bbr->bw_probe_up_acked += ack->bytes_delivered;

  if (bbr->bw_probe_up_acked >= bbr->probe_up_acked_per_inc) {
    delta = bbr->bw_probe_up_acked / bbr->probe_up_acked_per_inc;
    bbr->bw_probe_up_acked -= delta * bbr->probe_up_acked_per_inc;
    bbr->inflight_longterm += delta * cstat->max_tx_udp_payload_size;
  }

  if (bbr->round_start) {
    bbr_raise_inflight_longterm_slope(bbr, cstat);
  }
}

static int bbr_adapt_longterm_model(quicly_bbr_cc_bbr *bbr,
                                    const quicly_bbr_conn_stat *cstat,
                                    const quicly_bbr_cc_ack *ack) {
  if (bbr->ack_phase == QUICLY_BBR_BBR_ACK_PHASE_ACKS_PROBE_STARTING &&
      bbr->round_start) {
    bbr->ack_phase = QUICLY_BBR_BBR_ACK_PHASE_ACKS_PROBE_FEEDBACK;
  }

  if (bbr->ack_phase == QUICLY_BBR_BBR_ACK_PHASE_ACKS_PROBE_STOPPING &&
      bbr->round_start) {
    bbr->is_bw_probe_sample = 0;
    bbr->ack_phase = QUICLY_BBR_BBR_ACK_PHASE_ACKS_INIT;

    if (bbr_is_in_probe_bw_state(bbr) && !bbr->rst->rs.is_app_limited) {
      bbr_advance_max_bw_filter(bbr);
    }

    if (bbr_is_in_probe_bw_state(bbr) && bbr->prev_probe_precautionary &&
        !bbr->prev_probe_too_high) {
      bbr_start_probe_bw_refill(bbr);

      return 1;
    }
  }

  if (!bbr_is_inflight_too_high(bbr, &bbr->rst->rs)) {
    if (bbr->inflight_longterm == UINT64_MAX) {
      return 0;
    }

    if (bbr->rst->rs.tx_in_flight > bbr->inflight_longterm) {
      bbr->inflight_longterm = bbr->rst->rs.tx_in_flight;
    }

    if (bbr->state == QUICLY_BBR_BBR_STATE_PROBE_BW_UP) {
      bbr_probe_inflight_longterm_upward(bbr, cstat, ack);
    }
  }

  return 0;
}

static int bbr_is_time_to_probe_bw(quicly_bbr_cc_bbr *bbr,
                                   const quicly_bbr_conn_stat *cstat,
                                   quicly_bbr_tstamp ts) {
  if (bbr_has_elapsed_in_phase(bbr, bbr->bw_probe_wait, ts) ||
      bbr_is_reno_coexistence_probe_time(bbr, cstat)) {
    bbr_start_probe_bw_refill(bbr);

    return 1;
  }

  return 0;
}

static void bbr_pick_probe_wait(quicly_bbr_cc_bbr *bbr) {
  bbr->rounds_since_probe_up = quicly_bbr_pcg32_rand_n(bbr->pcg, 2);
  bbr->bw_probe_wait =
    2 * QUICLY_BBR_SECONDS + quicly_bbr_pcg32_rand_n(bbr->pcg, QUICLY_BBR_SECONDS + 1);
}

static int bbr_is_reno_coexistence_probe_time(const quicly_bbr_cc_bbr *bbr,
                                              const quicly_bbr_conn_stat *cstat) {
  uint64_t reno_rounds =
    bbr_target_inflight(bbr, cstat) / cstat->max_tx_udp_payload_size;

  return bbr->rounds_since_probe_up >= quicly_bbr_min(reno_rounds, 63);
}

static uint64_t bbr_target_inflight(const quicly_bbr_cc_bbr *bbr,
                                    const quicly_bbr_conn_stat *cstat) {
  return quicly_bbr_min(bbr->bdp, cstat->cwnd);
}

static int bbr_is_inflight_too_high(const quicly_bbr_cc_bbr *bbr,
                                    const quicly_bbr_rs *rs) {
  (void)bbr;
  return rs->lost * QUICLY_BBR_BBR_LOSS_THRESH_DENOM >
         rs->tx_in_flight * QUICLY_BBR_BBR_LOSS_THRESH_NUMER;
}

static void bbr_handle_inflight_too_high(quicly_bbr_cc_bbr *bbr,
                                         const quicly_bbr_conn_stat *cstat,
                                         const quicly_bbr_rs *rs,
                                         quicly_bbr_tstamp ts) {
  bbr->prev_probe_too_high = 1;
  bbr->is_bw_probe_sample = 0;

  if (!rs->is_app_limited) {
    bbr->inflight_longterm = quicly_bbr_max(
      rs->tx_in_flight, bbr_target_inflight(bbr, cstat) *
                          QUICLY_BBR_BBR_BETA_NUMER / QUICLY_BBR_BBR_BETA_DENOM);
  }

  if (bbr->state == QUICLY_BBR_BBR_STATE_PROBE_BW_UP) {
    bbr_start_probe_bw_down(bbr, ts);
  }
}

static void bbr_note_loss(quicly_bbr_cc_bbr *bbr, const quicly_bbr_conn_stat *cstat) {
  if (!bbr->is_loss_in_round) {
    bbr->loss_round_delivered = bbr->rst->delivered;
  }

  if (!bbr->undo_loss_in_round) {
    bbr_save_state_upon_loss(bbr, cstat);
    bbr->undo_loss_in_round = 1;
  }

  bbr->is_loss_in_round = 1;
}

static void bbr_save_state_upon_loss(quicly_bbr_cc_bbr *bbr,
                                     const quicly_bbr_conn_stat *cstat) {
  bbr_save_cwnd(bbr, cstat);
  bbr->undo_state = bbr->state;
  bbr->undo_bw_shortterm = bbr->bw_shortterm;
  bbr->undo_inflight_shortterm = bbr->inflight_shortterm;
  bbr->undo_inflight_longterm = bbr->inflight_longterm;
}

static void bbr_handle_spurious_loss_detection(quicly_bbr_cc_bbr *bbr,
                                               quicly_bbr_conn_stat *cstat) {
  bbr_restore_cwnd(bbr, cstat);

  bbr->is_loss_in_round = 0;
  bbr->undo_loss_in_round = 0;

  bbr_reset_full_bw(bbr);

  bbr->bw_shortterm = quicly_bbr_max(bbr->bw_shortterm, bbr->undo_bw_shortterm);
  bbr->inflight_shortterm =
    quicly_bbr_max(bbr->inflight_shortterm, bbr->undo_inflight_shortterm);
  bbr->inflight_longterm =
    quicly_bbr_max(bbr->inflight_longterm, bbr->undo_inflight_longterm);

  if (bbr->undo_state == QUICLY_BBR_BBR_STATE_STARTUP &&
      bbr->state != QUICLY_BBR_BBR_STATE_STARTUP) {
    bbr->full_bw_reached = 0;

    if (bbr->state != QUICLY_BBR_BBR_STATE_PROBE_RTT) {
      bbr_enter_startup(bbr);
    }
  } else if (bbr->undo_state == QUICLY_BBR_BBR_STATE_PROBE_BW_UP &&
             bbr->state != QUICLY_BBR_BBR_STATE_PROBE_BW_UP) {
    if (bbr->state != QUICLY_BBR_BBR_STATE_PROBE_RTT) {
      bbr_start_probe_bw_refill(bbr);
    }
  }

  bbr->undo_state = QUICLY_BBR_BBR_STATE_NONE;
}

static void bbr_handle_lost_packet(quicly_bbr_cc_bbr *bbr,
                                   const quicly_bbr_conn_stat *cstat,
                                   const quicly_bbr_cc_pkt *pkt, quicly_bbr_tstamp ts) {
  quicly_bbr_rs rs = {0};

  bbr_note_loss(bbr, cstat);

  if (!bbr->is_bw_probe_sample) {
    return;
  }

  rs.tx_in_flight = pkt->tx_in_flight;
  assert(bbr->rst->lost >= pkt->lost);
  rs.lost = bbr->rst->lost - pkt->lost;
  rs.is_app_limited = pkt->is_app_limited;

  if (bbr_is_inflight_too_high(bbr, &rs)) {
    rs.tx_in_flight = bbr_inflight_at_loss(bbr, pkt, &rs);

    bbr_handle_inflight_too_high(bbr, cstat, &rs, ts);
  }
}

static uint64_t bbr_inflight_at_loss(const quicly_bbr_cc_bbr *bbr,
                                     const quicly_bbr_cc_pkt *pkt,
                                     const quicly_bbr_rs *rs) {
  uint64_t inflight_prev, lost_prev, lost_prefix;
  (void)bbr;

  assert(rs->tx_in_flight >= pkt->pktlen);

  inflight_prev = rs->tx_in_flight - pkt->pktlen;

  assert(rs->lost >= pkt->pktlen);

  lost_prev = rs->lost - pkt->pktlen;

  if (inflight_prev * QUICLY_BBR_BBR_LOSS_THRESH_NUMER <
      lost_prev * QUICLY_BBR_BBR_LOSS_THRESH_DENOM) {
    return inflight_prev;
  }

  lost_prefix = (inflight_prev * QUICLY_BBR_BBR_LOSS_THRESH_NUMER -
                 lost_prev * QUICLY_BBR_BBR_LOSS_THRESH_DENOM) /
                (QUICLY_BBR_BBR_LOSS_THRESH_DENOM - QUICLY_BBR_BBR_LOSS_THRESH_NUMER);

  return inflight_prev + lost_prefix;
}

static void bbr_update_min_rtt(quicly_bbr_cc_bbr *bbr, const quicly_bbr_cc_ack *ack,
                               quicly_bbr_tstamp ts) {
  int min_rtt_expired;

  bbr->probe_rtt_expired =
    ts > bbr->probe_rtt_min_stamp + QUICLY_BBR_BBR_PROBE_RTT_INTERVAL;

  if (ack->rtt != UINT64_MAX &&
      (ack->rtt < bbr->probe_rtt_min_delay || bbr->probe_rtt_expired)) {
    bbr->probe_rtt_min_delay = ack->rtt;
    bbr->probe_rtt_min_stamp = ts;
  }

  min_rtt_expired = ts > bbr->min_rtt_stamp + QUICLY_BBR_BBR_MIN_RTT_FILTERLEN;

  if (bbr->probe_rtt_min_delay < bbr->min_rtt || min_rtt_expired) {
    bbr->min_rtt = bbr->probe_rtt_min_delay;
    bbr->min_rtt_stamp = bbr->probe_rtt_min_stamp;

    quicly_bbr_log_infof(bbr->cc.log, QUICLY_BBR_LOG_EVENT_CCA,
                     "bbr update min_rtt=", bbr->min_rtt);
  }
}

static void bbr_check_probe_rtt(quicly_bbr_cc_bbr *bbr, quicly_bbr_conn_stat *cstat,
                                quicly_bbr_tstamp ts) {
  if (bbr->state != QUICLY_BBR_BBR_STATE_PROBE_RTT && bbr->probe_rtt_expired &&
      !bbr->idle_restart) {
    bbr_enter_probe_rtt(bbr);
    bbr_save_cwnd(bbr, cstat);

    bbr->probe_rtt_done_stamp = UINT64_MAX;
    bbr->ack_phase = QUICLY_BBR_BBR_ACK_PHASE_ACKS_PROBE_STOPPING;

    bbr_start_round(bbr);
  }

  if (bbr->state == QUICLY_BBR_BBR_STATE_PROBE_RTT) {
    bbr_handle_probe_rtt(bbr, cstat, ts);
  }

  if (bbr->rst->rs.delivered) {
    bbr->idle_restart = 0;
  }
}

static void bbr_enter_probe_rtt(quicly_bbr_cc_bbr *bbr) {
  quicly_bbr_log_info(bbr->cc.log, QUICLY_BBR_LOG_EVENT_CCA, "bbr enter ProbeRTT");

  bbr->state = QUICLY_BBR_BBR_STATE_PROBE_RTT;
  bbr->pacing_gain_h = 100;
  bbr->cwnd_gain_h = QUICLY_BBR_BBR_PROBE_RTT_CWND_GAIN_H;
}

static void bbr_handle_probe_rtt(quicly_bbr_cc_bbr *bbr, quicly_bbr_conn_stat *cstat,
                                 quicly_bbr_tstamp ts) {
  bbr_mark_connection_app_limited(bbr, cstat);

  if (bbr->probe_rtt_done_stamp == UINT64_MAX &&
      cstat->bytes_in_flight <= bbr_probe_rtt_cwnd(bbr, cstat)) {
    bbr->probe_rtt_done_stamp = ts + QUICLY_BBR_BBR_PROBE_RTT_DURATION;
    bbr->probe_rtt_round_done = 0;

    bbr_start_round(bbr);

    return;
  }

  if (bbr->probe_rtt_done_stamp != UINT64_MAX) {
    if (bbr->round_start) {
      bbr->probe_rtt_round_done = 1;
    }

    if (bbr->probe_rtt_round_done) {
      bbr_check_probe_rtt_done(bbr, cstat, ts);
    }
  }
}

static void bbr_check_probe_rtt_done(quicly_bbr_cc_bbr *bbr,
                                     quicly_bbr_conn_stat *cstat,
                                     quicly_bbr_tstamp ts) {
  if (bbr->probe_rtt_done_stamp != UINT64_MAX &&
      ts > bbr->probe_rtt_done_stamp) {
    bbr->probe_rtt_min_stamp = ts;
    bbr_restore_cwnd(bbr, cstat);
    bbr_exit_probe_rtt(bbr, ts);
  }
}

static void bbr_mark_connection_app_limited(quicly_bbr_cc_bbr *bbr,
                                            const quicly_bbr_conn_stat *cstat) {
  bbr->rst->app_limited =
    quicly_bbr_max(bbr->rst->delivered + cstat->bytes_in_flight, 1);
}

static void bbr_exit_probe_rtt(quicly_bbr_cc_bbr *bbr, quicly_bbr_tstamp ts) {
  bbr_reset_shortterm_model(bbr);

  if (bbr->full_bw_reached) {
    bbr_start_probe_bw_down(bbr, ts);
    bbr_start_probe_bw_cruise(bbr);
  } else {
    bbr_enter_startup(bbr);
  }
}

static void bbr_handle_restart_from_idle(quicly_bbr_cc_bbr *bbr,
                                         quicly_bbr_conn_stat *cstat,
                                         quicly_bbr_tstamp ts) {
  if (cstat->bytes_in_flight == 0 && bbr->rst->app_limited) {
    quicly_bbr_log_info(bbr->cc.log, QUICLY_BBR_LOG_EVENT_CCA, "bbr restart from idle");

    bbr->idle_restart = 1;
    bbr->extra_acked_interval_start = ts;

    if (bbr_is_in_probe_bw_state(bbr)) {
      bbr_set_pacing_rate_with_gain(bbr, cstat, 100);
    } else if (bbr->state == QUICLY_BBR_BBR_STATE_PROBE_RTT) {
      bbr_check_probe_rtt_done(bbr, cstat, ts);
    }
  }
}

static uint64_t bbr_bdp_multiple(quicly_bbr_cc_bbr *bbr, uint64_t gain_h) {
  if (bbr->min_rtt == UINT64_MAX) {
    return bbr->initial_cwnd;
  }

  if (bbr->min_rtt &&
      bbr->bw > QUICLY_BBR_BBR_MAX_BDP * QUICLY_BBR_SECONDS / bbr->min_rtt) {
    bbr->bdp = QUICLY_BBR_BBR_MAX_BDP;
  } else {
    bbr->bdp = quicly_bbr_max(bbr->bw * bbr->min_rtt / QUICLY_BBR_SECONDS, 1);
  }

  return (uint64_t)(bbr->bdp * gain_h / 100);
}

static uint64_t min_pipe_cwnd(size_t max_udp_payload_size) {
  return max_udp_payload_size * 4;
}

static uint64_t bbr_quantization_budget(quicly_bbr_cc_bbr *bbr,
                                        const quicly_bbr_conn_stat *cstat,
                                        uint64_t inflight) {
  bbr_update_offload_budget(bbr, cstat);

  inflight = quicly_bbr_max(inflight, bbr->offload_budget);
  inflight =
    quicly_bbr_max(inflight, min_pipe_cwnd(cstat->max_tx_udp_payload_size));

  if (bbr->state == QUICLY_BBR_BBR_STATE_PROBE_BW_UP) {
    inflight += 2 * cstat->max_tx_udp_payload_size;
  }

  return inflight;
}

static uint64_t bbr_inflight(quicly_bbr_cc_bbr *bbr, const quicly_bbr_conn_stat *cstat,
                             uint64_t gain_h) {
  uint64_t inflight = bbr_bdp_multiple(bbr, gain_h);

  return bbr_quantization_budget(bbr, cstat, inflight);
}

static void bbr_update_max_inflight(quicly_bbr_cc_bbr *bbr,
                                    const quicly_bbr_conn_stat *cstat) {
  uint64_t inflight;

  inflight = bbr_bdp_multiple(bbr, bbr->cwnd_gain_h) + bbr->extra_acked;
  bbr->max_inflight = bbr_quantization_budget(bbr, cstat, inflight);
}

static void bbr_update_offload_budget(quicly_bbr_cc_bbr *bbr,
                                      const quicly_bbr_conn_stat *cstat) {
  bbr->offload_budget = 3 * cstat->send_quantum;
}

static void bbr_advance_max_bw_filter(quicly_bbr_cc_bbr *bbr) {
  ++bbr->cycle_count;
}

static void bbr_save_cwnd(quicly_bbr_cc_bbr *bbr, const quicly_bbr_conn_stat *cstat) {
  if (!bbr->in_loss_recovery && bbr->state != QUICLY_BBR_BBR_STATE_PROBE_RTT) {
    bbr->prior_cwnd = cstat->cwnd;
    return;
  }

  bbr->prior_cwnd = quicly_bbr_max(bbr->prior_cwnd, cstat->cwnd);
}

static void bbr_restore_cwnd(const quicly_bbr_cc_bbr *bbr,
                             quicly_bbr_conn_stat *cstat) {
  cstat->cwnd = quicly_bbr_max(cstat->cwnd, bbr->prior_cwnd);
}

static uint64_t bbr_probe_rtt_cwnd(quicly_bbr_cc_bbr *bbr,
                                   const quicly_bbr_conn_stat *cstat) {
  uint64_t probe_rtt_cwnd =
    bbr_bdp_multiple(bbr, QUICLY_BBR_BBR_PROBE_RTT_CWND_GAIN_H);
  uint64_t mpcwnd = min_pipe_cwnd(cstat->max_tx_udp_payload_size);

  return quicly_bbr_max(probe_rtt_cwnd, mpcwnd);
}

static void bbr_bound_cwnd_for_probe_rtt(quicly_bbr_cc_bbr *bbr,
                                         quicly_bbr_conn_stat *cstat) {
  if (bbr->state == QUICLY_BBR_BBR_STATE_PROBE_RTT) {
    cstat->cwnd = quicly_bbr_min(cstat->cwnd, bbr_probe_rtt_cwnd(bbr, cstat));
  }
}

static void bbr_set_cwnd(quicly_bbr_cc_bbr *bbr, quicly_bbr_conn_stat *cstat,
                         const quicly_bbr_cc_ack *ack) {
  uint64_t mpcwnd;

  bbr_update_max_inflight(bbr, cstat);

  if (bbr->full_bw_reached) {
    cstat->cwnd += ack->bytes_delivered;
    cstat->cwnd = quicly_bbr_min(cstat->cwnd, bbr->max_inflight);
  } else if (cstat->cwnd < bbr->max_inflight ||
             bbr->rst->delivered < bbr->initial_cwnd) {
    cstat->cwnd += ack->bytes_delivered;
  }

  mpcwnd = min_pipe_cwnd(cstat->max_tx_udp_payload_size);
  cstat->cwnd = quicly_bbr_max(cstat->cwnd, mpcwnd);

  bbr_bound_cwnd_for_probe_rtt(bbr, cstat);
  bbr_bound_cwnd_for_model(bbr, cstat);
}

static void bbr_bound_cwnd_for_model(const quicly_bbr_cc_bbr *bbr,
                                     quicly_bbr_conn_stat *cstat) {
  uint64_t cap = UINT64_MAX;
  uint64_t mpcwnd = min_pipe_cwnd(cstat->max_tx_udp_payload_size);

  if (bbr_is_in_probe_bw_state(bbr) &&
      bbr->state != QUICLY_BBR_BBR_STATE_PROBE_BW_CRUISE) {
    cap = bbr->inflight_longterm;
  } else if (bbr->state == QUICLY_BBR_BBR_STATE_PROBE_RTT ||
             bbr->state == QUICLY_BBR_BBR_STATE_PROBE_BW_CRUISE) {
    cap = bbr_inflight_with_headroom(bbr, cstat);
  }

  cap = quicly_bbr_min(cap, bbr->inflight_shortterm);
  cap = quicly_bbr_max(cap, mpcwnd);

  cstat->cwnd = quicly_bbr_min(cstat->cwnd, cap);
}

static void bbr_set_send_quantum(const quicly_bbr_cc_bbr *bbr,
                                 quicly_bbr_conn_stat *cstat) {
  size_t send_quantum = 64 * 1024;
  (void)bbr;

  send_quantum = quicly_bbr_min(send_quantum, (size_t)((QUICLY_BBR_MILLISECONDS << 10) /
                                                   cstat->pacing_interval_m));

  cstat->send_quantum =
    quicly_bbr_max(send_quantum, 2 * cstat->max_tx_udp_payload_size);
}

static int in_congestion_recovery(const quicly_bbr_conn_stat *cstat,
                                  quicly_bbr_tstamp sent_time) {
  return cstat->congestion_recovery_start_ts != UINT64_MAX &&
         sent_time <= cstat->congestion_recovery_start_ts;
}

static void bbr_handle_recovery(quicly_bbr_cc_bbr *bbr, quicly_bbr_conn_stat *cstat,
                                const quicly_bbr_cc_ack *ack) {
  if (!bbr->in_loss_recovery) {
    return;
  }

  if (ack->largest_pkt_sent_ts != UINT64_MAX &&
      !in_congestion_recovery(cstat, ack->largest_pkt_sent_ts)) {
    bbr->in_loss_recovery = 0;
    bbr->round_count_at_recovery = UINT64_MAX;
    bbr_restore_cwnd(bbr, cstat);
  }
}

static void bbr_cc_on_pkt_lost(quicly_bbr_cc *cc, quicly_bbr_conn_stat *cstat,
                               const quicly_bbr_cc_pkt *pkt, quicly_bbr_tstamp ts) {
  quicly_bbr_cc_bbr *bbr = quicly_bbr_struct_of(cc, quicly_bbr_cc_bbr, cc);

  bbr_handle_lost_packet(bbr, cstat, pkt, ts);
}

static void bbr_cc_congestion_event(quicly_bbr_cc *cc, quicly_bbr_conn_stat *cstat,
                                    quicly_bbr_tstamp sent_ts,
                                    const quicly_bbr_cc_ack *ack,
                                    quicly_bbr_tstamp ts) {
  quicly_bbr_cc_bbr *bbr = quicly_bbr_struct_of(cc, quicly_bbr_cc_bbr, cc);
  (void)ack;

  if (bbr->in_loss_recovery || in_congestion_recovery(cstat, sent_ts)) {
    return;
  }

  bbr->in_loss_recovery = 1;
  bbr->round_count_at_recovery =
    bbr->round_start ? bbr->round_count : bbr->round_count + 1;

  cstat->congestion_recovery_start_ts = ts;
}

static void bbr_cc_on_spurious_congestion(quicly_bbr_cc *cc,
                                          quicly_bbr_conn_stat *cstat,
                                          quicly_bbr_tstamp ts) {
  quicly_bbr_cc_bbr *bbr = quicly_bbr_struct_of(cc, quicly_bbr_cc_bbr, cc);
  (void)ts;

  cstat->congestion_recovery_start_ts = UINT64_MAX;

  bbr->in_loss_recovery = 0;
  bbr->round_count_at_recovery = UINT64_MAX;

  bbr_handle_spurious_loss_detection(bbr, cstat);
}

static void bbr_cc_on_persistent_congestion(quicly_bbr_cc *cc,
                                            quicly_bbr_conn_stat *cstat,
                                            quicly_bbr_tstamp ts) {
  quicly_bbr_cc_bbr *bbr = quicly_bbr_struct_of(cc, quicly_bbr_cc_bbr, cc);
  (void)ts;

  cstat->congestion_recovery_start_ts = UINT64_MAX;
  bbr->in_loss_recovery = 0;
  bbr->round_count_at_recovery = UINT64_MAX;

  cstat->cwnd = cstat->bytes_in_flight + cstat->max_tx_udp_payload_size;
  cstat->cwnd =
    quicly_bbr_max(cstat->cwnd, min_pipe_cwnd(cstat->max_tx_udp_payload_size));
}

static void bbr_cc_on_ack_recv(quicly_bbr_cc *cc, quicly_bbr_conn_stat *cstat,
                               const quicly_bbr_cc_ack *ack, quicly_bbr_tstamp ts) {
  quicly_bbr_cc_bbr *bbr = quicly_bbr_struct_of(cc, quicly_bbr_cc_bbr, cc);

  bbr_handle_recovery(bbr, cstat, ack);

  if (ack->bytes_delivered == 0) {
    return;
  }

  bbr_update_on_ack(bbr, cstat, ack, ts);
}

static void bbr_cc_on_pkt_sent(quicly_bbr_cc *cc, quicly_bbr_conn_stat *cstat,
                               const quicly_bbr_cc_pkt *pkt) {
  quicly_bbr_cc_bbr *bbr = quicly_bbr_struct_of(cc, quicly_bbr_cc_bbr, cc);

  bbr_on_transmit(bbr, cstat, pkt->sent_ts);
}

static void bbr_cc_reset(quicly_bbr_cc *cc, quicly_bbr_conn_stat *cstat,
                         quicly_bbr_tstamp ts) {
  quicly_bbr_cc_bbr *bbr = quicly_bbr_struct_of(cc, quicly_bbr_cc_bbr, cc);

  bbr_on_init(bbr, cstat, ts);
}

void quicly_bbr_cc_bbr_init(quicly_bbr_cc_bbr *bbr, quicly_bbr_log *log,
                        quicly_bbr_conn_stat *cstat, quicly_bbr_rst *rst,
                        quicly_bbr_tstamp initial_ts, quicly_bbr_pcg32 *pcg) {
  *bbr = (quicly_bbr_cc_bbr){
    .cc =
      {
        .log = log,
        .on_pkt_lost = bbr_cc_on_pkt_lost,
        .congestion_event = bbr_cc_congestion_event,
        .on_spurious_congestion = bbr_cc_on_spurious_congestion,
        .on_persistent_congestion = bbr_cc_on_persistent_congestion,
        .on_ack_recv = bbr_cc_on_ack_recv,
        .on_pkt_sent = bbr_cc_on_pkt_sent,
        .reset = bbr_cc_reset,
      },
    .rst = rst,
    .pcg = pcg,
    .initial_cwnd = cstat->cwnd,
  };

  bbr_on_init(bbr, cstat, initial_ts);
}


