#define QUICLY_BBR_PCG_DEFAULT_MULTIPLIER_64 6364136223846793005ULL
#define QUICLY_BBR_PCG_DEFAULT_INCREMENT_64 1442695040888963407ULL

static void pcg_oneseq_64_step_r(quicly_bbr_pcg32 *pcg) {
  pcg->state = pcg->state * QUICLY_BBR_PCG_DEFAULT_MULTIPLIER_64 +
               QUICLY_BBR_PCG_DEFAULT_INCREMENT_64;
}

void quicly_bbr_pcg32_init(quicly_bbr_pcg32 *pcg, uint64_t seed) {
  pcg->state = 0;
  pcg_oneseq_64_step_r(pcg);
  pcg->state += seed;
  pcg_oneseq_64_step_r(pcg);
}

static uint32_t pcg_rotr_32(uint32_t value, unsigned int rot) {
  return (value >> rot) | (value << ((32 - rot) & 31));
}

static uint32_t pcg_output_xsh_rr_64_32(uint64_t state) {
  return pcg_rotr_32((uint32_t)(((state >> 18U) ^ state) >> 27U),
                     (unsigned int)(state >> 59U));
}

uint32_t quicly_bbr_pcg32_rand(quicly_bbr_pcg32 *pcg) {
  uint64_t oldstate = pcg->state;

  pcg_oneseq_64_step_r(pcg);

  return pcg_output_xsh_rr_64_32(oldstate);
}

uint32_t quicly_bbr_pcg32_rand_n(quicly_bbr_pcg32 *pcg, uint32_t n) {
  assert(n);
  return (uint32_t)(((uint64_t)quicly_bbr_pcg32_rand(pcg) * n) >> 32);
}
